head.script:
scwin.getStroke = function() {
    var className;
    if (chart_ref1.options.version == "3.7") {
      className = 'raphael-group-53-connector';
    } else if (chart_ref1.options.version == "3.11") {
        className = 'raphael-group-77-line-connector';
    } else if (chart_ref1.options.version == "3.13") {
        className = 'raphael-group-38-line';
    } else if (chart_ref1.options.version == "3.15") {
        className = 'raphael-group-40-line';
    }
    var el = document.getElementsByClassName(className);
    if (chart_ref1.options.version == "3.19" || chart_ref1.options.version == "3.23" || chart_ref1.options.version.startsWith('4')) {
        el = document.querySelectorAll('[class*="common-elems-group"]')
    }
    var stroke;
    if (el[0]) {
        stroke = el[0].getElementsByTagName("path")[0].getAttribute("stroke");
    }    
    return stroke == '#ff0000';
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 0. fuctionChart속성의 lineColor속성을 빨강색으로 설정한다.(lineColor="ff0000") 
    //0. Set the lineColor property of the fuctionChart property to red (lineColor = "ff0000").
    //Verify step 0. lineColor="ff0000"
    //0. lineColor = "ff0000"
    //Test step 1. 샘플파일을 실행하여 lineColor속성을 확인한다.
    //1. Run the sample file to check the lineColor attribute.
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 1. lineColor의 색상이 빨강색으로 보여진다.(이전에는 속성이 먹히지 않았음)
    //1. The color of lineColor is shown in red (the property was not edited before)
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.red-line-connector-48 path').attr('stroke') == '#ff0000'", "true");
    //if (chart_ref1.options.version == "3.3.1") {
    //  WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('[class*=\"red-line-connector-\"] path').attr('stroke') == '#ff0000'", "true");
    //} else if (chart_ref1.options.version == "3.7") {
    //  WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.raphael-group-53-connector path').attr('stroke') == '#ff0000'", "true");
    //} else if (chart_ref1.options.version == "3.11") {
    //  WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.raphael-group-77-line-connector path').attr('stroke') == '#ff0000'", "true");
    //} else if (chart_ref1.options.version == "3.13") {
    // WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.raphael-group-38-line path').attr('stroke') == '#ff0000'", "true");
    //} else if (chart_ref1.options.version == "3.15" || chart_ref1.options.version == "3.19") {
    //  WebSquare.wUnit.addCommand("assert", "scwin.getStroke('raphael-group-40-line') == '#ff0000'", "true");
    //}
    WebSquare.wUnit.addCommand("assert", "scwin.getStroke()", "true");

    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
